// Differential checks of PrimOpString03-pbo.js against Lean, generated by leanscript --check
import * as M from "./PrimOpString03-pbo.js";

function show(v) {
  if (Array.isArray(v) || ArrayBuffer.isView(v)) return "#[" + [...v].map(show).join(", ") + "]";
  // a list of cons cells (`ListRepr.taggedUnion`) is shown as its elements
  if (v !== null && typeof v === "object" && (v.tag === 0 || v.tag === 1)) {
    const a = [];
    for (; v.tag === 1; v = v._2) a.push(v._1);
    return show(a);
  }
  return String(v);
}
function floatBits(x) {
  return String(new BigUint64Array(new Float64Array([x]).buffer)[0]);
}
function isNaNBits(s) {
  const b = BigInt(s);
  return ((b >> 52n) & 0x7ffn) === 0x7ffn && (b & 0xfffffffffffffn) !== 0n;
}
let passed = 0, failed = 0;
function check(label, thunk, expected, isFloat) {
  let got;
  try {
    const v = thunk();
    got = isFloat ? floatBits(v) : show(v);
    // NaN payloads differ between platforms: any NaN matches any NaN
    if (isFloat && Number.isNaN(v) && isNaNBits(expected)) got = expected;
  } catch (e) {
    got = "threw: " + e.message;
  }
  if (got === expected) passed++;
  else {
    failed++;
    console.log(`FAIL ${label}: expected ${JSON.stringify(expected)}, got ${JSON.stringify(got)}`);
  }
}

check("test1(\"\")", () => M.test1(""), "abcd", false);
check("test1(\"a\")", () => M.test1("a"), "abacd", false);
check("test1(\"hello world\")", () => M.test1("hello world"), "abhello worldcd", false);
check("test1(\"héllo, wörld\")", () => M.test1("héllo, wörld"), "abhéllo, wörldcd", false);
check("test1(\"abcabc\")", () => M.test1("abcabc"), "ababcabccd", false);
check("test2(\"\")", () => M.test2(""), "abcd", false);
check("test2(\"a\")", () => M.test2("a"), "abacd", false);
check("test2(\"hello world\")", () => M.test2("hello world"), "abhello worldcd", false);
check("test2(\"héllo, wörld\")", () => M.test2("héllo, wörld"), "abhéllo, wörldcd", false);
check("test2(\"abcabc\")", () => M.test2("abcabc"), "ababcabccd", false);
check("test3(\"\")", () => M.test3(""), "abcd", false);
check("test3(\"a\")", () => M.test3("a"), "abacd", false);
check("test3(\"hello world\")", () => M.test3("hello world"), "abhello worldcd", false);
check("test3(\"héllo, wörld\")", () => M.test3("héllo, wörld"), "abhéllo, wörldcd", false);
check("test3(\"abcabc\")", () => M.test3("abcabc"), "ababcabccd", false);

console.log(`PrimOpString03-pbo.js: ${passed} passed, ${failed} failed`);
if (failed > 0) process.exit(1);
